/**
 * Invert ch1 → |distance|.
 * Table is distance-ascending / ch1-descending. Linear interpolation.
 * @return 0 on success; -1 if out is NULL.
 * Caller MUST inspect *out_quality: 0 good, 1 fair, 2 poor, 3 saturated
 * (do not trust distance when quality >= 3).
 */
static inline int coil_ch1_to_distance_01mm(uint32_t ch1, int *out_01mm, uint8_t *out_quality)
{
    if (!out_01mm) {
        return -1;
    }
    const coil_dist_lut_entry_t *t = kCoilDistLut;
    const int n = COIL_DIST_LUT_LEN;
    if (ch1 >= t[0].ch1) {
        *out_01mm = (int)t[0].dist_01mm;
        if (out_quality) {
            *out_quality = t[0].quality;
        }
        return 0;
    }
    if (ch1 <= t[n - 1].ch1) {
        *out_01mm = (int)t[n - 1].dist_01mm;
        if (out_quality) {
            *out_quality = t[n - 1].quality;
        }
        return 0;
    }
    int lo = 0;
    int hi = n - 1;
    while (hi - lo > 1) {
        int mid = (lo + hi) / 2;
        if (t[mid].ch1 >= ch1) {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    /* Must subtract in signed domain: ch1 < y0 is the normal case, and
     * uint32_t (ch1 - y0) wraps to ~4e9, which made est a large negative. */
    int32_t y0 = (int32_t)t[lo].ch1;
    int32_t y1 = (int32_t)t[hi].ch1;
    int32_t x0 = (int32_t)t[lo].dist_01mm;
    int32_t x1 = (int32_t)t[hi].dist_01mm;
    int32_t dc = (int32_t)ch1 - y0;
    int32_t dy = y1 - y0;
    if (dy == 0) {
        *out_01mm = (int)x0;
    } else {
        *out_01mm = (int)(x0 + (int32_t)(((int64_t)dc * (x1 - x0)) / dy));
    }
    if (out_quality) {
        uint8_t q = t[lo].quality;
        if (t[hi].quality > q) {
            q = t[hi].quality;
        }
        *out_quality = q;
    }
    return 0;
}
